test("memory edit cannot switch records while a save is in flight", async ({ page }) => {
  const firstMemory: AdminMemory = {
    ...rynekMemory,
    admin_audio: null,
    admin_public_path: "/api/admin/memories/save-lock-a/media/image",
    admin_thumb_path: "/api/admin/memories/save-lock-a/media/thumb",
    approved_at: null,
    id: "save-lock-a",
    place_id: adminPlaces[0].id,
    share_slug: "save-lock-a",
    status: "pending",
  };
  const secondMemory: AdminMemory = {
    ...firstMemory,
    admin_public_path: "/api/admin/memories/save-lock-b/media/image",
    admin_thumb_path: "/api/admin/memories/save-lock-b/media/thumb",
    caption: "Druga pamiątka",
    id: "save-lock-b",
    share_slug: "save-lock-b",
  };
  let releaseSave!: () => void;
  const saveGate = new Promise<void>((resolve) => {
    releaseSave = resolve;
  });

  await mockAdminApi(page, { adminMemoryList: [firstMemory, secondMemory], adminPlaceList: [adminPlaces[0]] });
  await page.route(`${API_URL}/api/admin/memories/${firstMemory.id}`, async (route) => {
    if (route.request().method() !== "PATCH") {
      await route.fallback();
      return;
    }
    await saveGate;
    await route.fulfill({ json: firstMemory });
  });

  await unlockAdmin(page);
  await openModeration(page, /Pamiątki/);
  const firstItem = page.locator(".admin-media-item").filter({ hasText: firstMemory.caption }).first();
  const secondItem = page.locator(".admin-media-item").filter({ hasText: secondMemory.caption }).first();

  await firstItem.getByRole("button", { name: "Edytuj pamiątkę" }).click();
  await firstItem.getByRole("button", { name: "Zapisz" }).click();
  await expect(firstItem.getByRole("button", { name: "Anuluj" })).toBeDisabled();
  await expect(secondItem.getByRole("button", { name: "Edytuj pamiątkę" })).toBeDisabled();

  releaseSave();
  await expect(secondItem.getByRole("button", { name: "Edytuj pamiątkę" })).toBeEnabled();
});
